content.arguments:
{"command": "mkdir -p deploy/prometheus deploy/grafana/provisioning/datasources deploy/grafana/provisioning/dashboards deploy/grafana/dashboards
cat > deploy/prometheus/prometheus.yml <<'EOF'
global:
  scrape_interval: 15s
  evaluation_interval: 15s

scrape_configs:
  - job_name: agent-hub
    metrics_path: /metrics
    static_configs:
      - targets: ["api:8000"]
    # 若设置了 METRICS_TOKEN，放开下面三行并把 <token> 换成实际值：
    # authorization:
    #   type: Bearer
    #   credentials: <token>
EOF
cat > deploy/grafana/provisioning/datasources/datasource.yml <<'EOF'
apiVersion: 1

datasources:
  - name: Prometheus
    uid: prometheus
    type: prometheus
    access: proxy
    url: http://prometheus:9090
    isDefault: true
    editable: false
EOF
cat > deploy/grafana/provisioning/dashboards/dashboards.yml <<'EOF'
apiVersion: 1

providers:
  - name: agent-hub
    orgId: 1
    folder: Agent Hub
    type: file
    disableDeletion: false
    updateIntervalSeconds: 30
    options:
      path: /var/lib/grafana/dashboards
EOF
cat > deploy/nginx.conf <<'EOF'
# 生产反代示例：SSE 关闭缓冲、长读超时。
upstream agent_hub {
    server api:8000;
    keepalive 32;
}

server {
    listen 80;
    server_name _;
    client_max_body_size 25m;

    location / {
        proxy_pass http://agent_hub;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";

        # SSE：不能缓冲，读超时要覆盖 HITL 等待窗口
        proxy_buffering off;
        proxy_cache off;
        proxy_read_timeout 900s;
        proxy_send_timeout 900s;
        add_header X-Accel-Buffering no;
    }
}
EOF
echo done", "description": "写入 Prometheus/Grafana/Nginx 配置"}

